def tri(n):
    """Calculate the first n + 1 numbers of the Tribonacci sequence."""
    def tribonacci_value(k, memo):
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 1  # Define tri(0) as 1 for clarity
        elif k == 1:
            memo[k] = 3
        elif k % 2 == 0:  # Even case
            memo[k] = int(1 + k / 2)  # Ensure result is an integer
        else:  # Odd case
            if k + 1 not in memo:  # Ensure k + 1 is calculated when needed
                memo[k + 1] = tribonacci_value(k + 1, memo)
            memo[k] = tribonacci_value(k - 1, memo) + tribonacci_value(k - 2, memo) + memo[k + 1]
        return memo[k]

    memo = {}
    result = []
    for i in range(n + 1):
        result.append(tribonacci_value(i, memo))
    return result
